<?php
declare(strict_types=1);
require_once __DIR__ . '/../common/migrate.php';
$options=getopt('', ['fixture:', 'source-port:', 'target-port:', 'runtime:']);
$fixture=realpath((string)($options['fixture']??''));
if($fixture===false || !preg_match('~/lightem-standalone-maptest-[A-Za-z0-9_-]+$~',$fixture)) throw new RuntimeException('A disposable named-database migration fixture is required.');
$runtime=realpath((string)($options['runtime']??''));
if($runtime===false || str_contains($runtime,'/Applications/XAMPP')) throw new RuntimeException('Use the independent runtime.');
$sourcePort=lightemDatabasePort($options['source-port']??0);$targetPort=lightemDatabasePort($options['target-port']??0);
$sourceAdmin=lightemConnect(['host'=>'127.0.0.1','port'=>$sourcePort,'user'=>'root','pass'=>lightemReadRootPassword($fixture.'/source-root.txt')]);
$targetAdmin=lightemConnect(['host'=>'127.0.0.1','port'=>$targetPort,'user'=>'root','pass'=>lightemReadRootPassword($fixture.'/target-root.txt')]);
lightemVerifyPrivateDatabase($sourceAdmin,$fixture.'/source-data',$sourcePort);
lightemVerifyPrivateDatabase($targetAdmin,$fixture.'/target-data',$targetPort);
$count=0;
function mappedCheck(bool $condition,string $label):void {global $count;if(!$condition)throw new RuntimeException('FAIL '.$label);$count++;echo 'PASS '.$label.PHP_EOL;}
$seams=['writeRuntimeSecret'=>static fn(string $file,string $contents)=>lightemWriteFile($file,$contents,0600,true)];
$sourceRoot=$fixture.'/source-backend';$targetRoot=$fixture.'/target-backend';$payload=$fixture.'/payload';
mkdir($fixture.'/source-backups',0700);mkdir($fixture.'/target-backups',0700);
lightemProvision(['root'=>$sourceRoot,'payload'=>$payload,'credentials'=>$fixture.'/source-access.txt','bootstrap-password-file'=>$fixture.'/source-root.txt','database-port'=>$sourcePort,'mysqldump-path'=>$runtime.'/bin/mysqldump','backup-dir'=>$fixture.'/source-backups'],$seams);
[$sourceEnv,$sourceConfig]=lightemSettings($sourceRoot);
// Rename only this fixture's freshly generated, empty application schemas.
// Production schema comes from installer/schema; no live/sample store is read.
$names=['db_cnc_pos'=>'festivalmall','reports_database'=>'festivalmall_report'];
foreach($names as $old=>$new){
 $sourceAdmin->exec('CREATE DATABASE '.lightemIdentifier($new).' CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci');
 $q=$sourceAdmin->prepare("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=? AND TABLE_TYPE='BASE TABLE'");$q->execute([$old]);
 foreach($q->fetchAll(PDO::FETCH_COLUMN) as $table)$sourceAdmin->exec('RENAME TABLE '.lightemIdentifier($old).'.'.lightemIdentifier($table).' TO '.lightemIdentifier($new).'.'.lightemIdentifier($table));
 $sourceAdmin->exec('DROP DATABASE '.lightemIdentifier($old));
 foreach(['localhost','127.0.0.1'] as $host)$sourceAdmin->exec('GRANT ALL PRIVILEGES ON '.lightemIdentifier($new).'.* TO '.$sourceAdmin->quote($sourceConfig['user']).'@'.$sourceAdmin->quote($host));
}
$sourceEnv['DB_NAME']='festivalmall';$sourceEnv['CUSTOM_LITERAL']='festivalmall / festivalmall_report must remain literal';
$sourceConfig['db']='festivalmall';$sourceConfig['report_db']='festivalmall_report';
file_put_contents($sourceRoot.'/.env',lightemSerializeEnvironment($sourceEnv));
file_put_contents($sourceRoot.'/api/config.php',"<?php\nreturn ".var_export($sourceConfig,true).";\n");
unlink($sourceRoot.'/'.LIGHTEM_MARKER);
$primary=lightemConnect($sourceConfig,'festivalmall');$report=lightemConnect($sourceConfig,'festivalmall_report');
$primary->exec("CREATE TABLE migration_names (id INT PRIMARY KEY, literal TEXT NULL, binary_value VARBINARY(255) NULL, amount DECIMAL(12,2)) COMMENT='festivalmall and festivalmall_report remain in comments'");
$literal="festivalmall.orders + `festivalmall_report`.`table`; quote' and \\ and newline\n";
$primary->prepare('INSERT INTO migration_names VALUES (?, ?, ?, ?)')->execute([1,$literal,"festivalmall\0festivalmall_report",'123.45']);
$primary->exec('INSERT INTO migration_names VALUES (2,NULL,NULL,-2.50)');
$report->exec('CREATE TABLE migration_report (id INT PRIMARY KEY,note TEXT)');
$report->prepare('INSERT INTO migration_report VALUES (?, ?)')->execute([1,'festivalmall_report.literal text']);
$report->exec('CREATE TABLE migration_audit (id INT PRIMARY KEY,note VARCHAR(100))');
$report->exec('CREATE TABLE migration_foreign (id INT PRIMARY KEY,CONSTRAINT mapping_fk FOREIGN KEY(id) REFERENCES festivalmall.migration_names(id))');
$report->exec('INSERT INTO migration_foreign VALUES (1)');
$primary->exec("CREATE VIEW migration_cross_view AS SELECT p.id,p.literal,r.note FROM festivalmall.migration_names p JOIN festivalmall_report.migration_report r ON p.id=r.id WHERE r.note LIKE 'festivalmall_report.%'");
$report->exec('CREATE VIEW migration_back_view AS SELECT id,literal FROM festivalmall.migration_names');
$primary->exec("CREATE TRIGGER migration_cross_trigger AFTER INSERT ON migration_names FOR EACH ROW INSERT INTO festivalmall_report.migration_audit VALUES(NEW.id,'festivalmall must remain literal')");
$primary->exec("CREATE PROCEDURE migration_cross_procedure() SELECT literal,'festivalmall_report' AS kept_literal FROM festivalmall.migration_names ORDER BY id");
$report->exec("CREATE EVENT migration_cross_event ON SCHEDULE EVERY 1 DAY DISABLE DO INSERT INTO festivalmall_report.migration_audit VALUES(99,'festivalmall_report literal event')");
$sourceRows=$primary->query('SELECT * FROM migration_names ORDER BY id')->fetchAll();
$sourceAdminHash=$primary->query("SELECT password FROM tbl_users_global_assignment WHERE email='admin'")->fetchColumn();
$envHash=hash_file('sha256',$sourceRoot.'/.env');$configHash=hash_file('sha256',$sourceRoot.'/api/config.php');
$args=['source-root'=>$sourceRoot,'root'=>$targetRoot,'payload'=>$payload,'credentials'=>$fixture.'/migration-access.txt','bootstrap-password-file'=>$fixture.'/target-root.txt','database-port'=>$targetPort,'data-dir'=>$fixture.'/target-data','mysqldump-path'=>$runtime.'/bin/mysqldump','mysql-path'=>$runtime.'/bin/mysql','backup-dir'=>$fixture.'/target-backups'];
$result=lightemMigrate($args,$seams);
[$targetEnv,$targetConfig]=lightemSettings($targetRoot);
$target=lightemConnect($targetConfig,'db_cnc_pos');$targetReport=lightemConnect($targetConfig,'reports_database');
mappedCheck($result['mode']==='migrated','recognized legacy names migrate to the fixed standalone names');
$originalDump=file_get_contents($result['backupFile']);
mappedCheck(str_contains($originalDump,'USE `festivalmall`;')&&str_contains($originalDump,'USE `festivalmall_report`;')&&!str_contains($originalDump,'USE `db_cnc_pos`;')&&!str_contains($originalDump,'USE `reports_database`;'),'recovery SQL retains the original source database names');
mappedCheck($targetEnv['DB_NAME']==='db_cnc_pos'&&$targetConfig['db']==='db_cnc_pos'&&$targetConfig['report_db']==='reports_database','both target configuration formats contain the fixed database names');
mappedCheck($targetEnv['CUSTOM_LITERAL']===$sourceEnv['CUSTOM_LITERAL'],'unrelated environment values retain legacy database names');
mappedCheck($target->query('SELECT * FROM migration_names ORDER BY id')->fetchAll()===$sourceRows,'text containing old names, quotes, binary, nulls and decimals is unchanged');
mappedCheck($target->query('SELECT * FROM migration_cross_view ORDER BY id')->fetchAll()===$primary->query('SELECT * FROM migration_cross_view ORDER BY id')->fetchAll(),'primary cross-database view resolves the mapped report database');
mappedCheck($targetReport->query('SELECT * FROM migration_back_view ORDER BY id')->fetchAll()===$report->query('SELECT * FROM migration_back_view ORDER BY id')->fetchAll(),'report cross-database view resolves the mapped primary database');
$definition=$target->query('SHOW CREATE TABLE migration_names')->fetch(PDO::FETCH_NUM)[1];
mappedCheck(str_contains($definition,'festivalmall and festivalmall_report remain in comments'),'table comments preserve original database words');
$fk=$targetAdmin->query("SELECT REFERENCED_TABLE_SCHEMA FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA='reports_database' AND TABLE_NAME='migration_foreign' AND REFERENCED_TABLE_NAME IS NOT NULL")->fetchColumn();
mappedCheck($fk==='db_cnc_pos','cross-database foreign key references the mapped primary database');
$event=$targetAdmin->query("SELECT EVENT_DEFINITION FROM information_schema.EVENTS WHERE EVENT_SCHEMA='reports_database' AND EVENT_NAME='migration_cross_event'")->fetchColumn();
mappedCheck(str_contains($event,'reports_database')&&str_contains($event,"'festivalmall_report literal event'"),'disabled event maps its schema reference while preserving its literal');
mappedCheck($target->query("SELECT password FROM tbl_users_global_assignment WHERE email='admin'")->fetchColumn()===$sourceAdminHash,'existing administrator password hash remains unchanged');
mappedCheck(hash_file('sha256',$sourceRoot.'/.env')===$envHash&&hash_file('sha256',$sourceRoot.'/api/config.php')===$configHash,'migration leaves source settings untouched');
mappedCheck((int)$targetAdmin->query("SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME IN ('festivalmall','festivalmall_report')")->fetchColumn()===0,'destination does not create legacy-named databases');
mappedCheck((int)$sourceAdmin->query("SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME IN ('festivalmall','festivalmall_report')")->fetchColumn()===2,'source retains its original database names');
mappedCheck(lightemMigrate($args,$seams)['mode']==='migrated-resumed','unchanged mapped migration resumes without reimporting data');
$target->exec("INSERT INTO migration_names VALUES (3,'post-migration',NULL,7.00)");
mappedCheck($targetReport->query('SELECT note FROM migration_audit WHERE id=3')->fetchColumn()==='festivalmall must remain literal','copied trigger writes into the mapped report database and preserves literal text');
$q=$target->query('CALL migration_cross_procedure()');$procedureRows=$q->fetchAll();$q->closeCursor();
mappedCheck(count($procedureRows)===3&&$procedureRows[0]['kept_literal']==='festivalmall_report','copied procedure reads the mapped database while preserving its literal');
mappedCheck($primary->query('SELECT * FROM migration_names ORDER BY id')->fetchAll()===$sourceRows&&(int)$report->query('SELECT COUNT(*) FROM migration_audit')->fetchColumn()===0,'new standalone writes do not modify either source database');
echo "Completed {$count} isolated mapped-database migration checks.\n";
